// Отдельная часть: качается только в сценарии ритейла, ядро и сервер не меняются (#191).
const CYR = "";
const LAT = "";
export const CSS = `@font-face { font-family: "Inter RT"; font-style: normal; font-display: swap; font-weight: 100 900;
  src: url(data:font/woff2;base64,${CYR}) format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116; }
@font-face { font-family: "Inter RT"; font-style: normal; font-display: swap; font-weight: 100 900;
  src: url(data:font/woff2;base64,${LAT}) format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }`;
export function init() { if (!document.getElementById("rtFont")) { const s = document.createElement("style"); s.id = "rtFont"; s.textContent = CSS; document.head.append(s); } }
